6	/// The port later epics extend (Code Map) — this story gives it exactly
7	/// one method, [create]. `features/capture/` depends on this abstract
8	/// class only, never `entries/data` or `entries/presentation` (RNF06).
9	abstract class EntriesRepository {
10	  /// Posts to `entries-create` (`ApiClient.post`, via
11	  /// `EntriesRemoteDataSource`) and, on success, writes the entry through
12	  /// to the `entries` Hive box before returning `Right` (Boundaries) — a
13	  /// caller that only reads the returned [Entry] never needs to touch the
14	  /// box itself. Every [Failure] — including
15	  /// [Failure.networkOffline] — is returned as `Left`, unmapped and
16	  /// un-retried; the caller decides what to do with it (RNF09).
17	  Future<Either<Failure, Entry>> create({
18	    required String content,
19	    required EntrySource source,
20	    int? mediaDurationSeconds,
21	  });
22	}
23

1	// The constructor keeps public named params (`remoteDataSource`,
2	// `entriesBox`) distinct from the private fields they initialize, matching
3	// `account_settings_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../domain/entities/entry.dart';
10	import '../../domain/repositories/entries_repository.dart';
11	import '../datasources/entries_remote_data_source.dart';
12	import '../models/entry_dto.dart';
13	
14	/// On success, writes the entry through to the `entries` Hive box (`Box
15	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
16	/// returning `right(...)`, same "persist then return" ordering
17	/// `AuthRepositoryImpl._authenticate` already uses for its own
18	/// post-success side effect.
19	class EntriesRepositoryImpl implements EntriesRepository {
20	  EntriesRepositoryImpl({
21	    required EntriesRemoteDataSource remoteDataSource,
22	    required Box<Map> entriesBox,
23	  }) : _remoteDataSource = remoteDataSource,
24	       _entriesBox = entriesBox;
25	
26	  final EntriesRemoteDataSource _remoteDataSource;
27	  final Box<Map> _entriesBox;
28	
29	  @override
30	  Future<Either<Failure, Entry>> create({
31	    required String content,
32	    required EntrySource source,
33	    int? mediaDurationSeconds,
34	  }) async {
35	    final result = await _remoteDataSource.create(
36	      content: content,
37	      source: source,
38	      mediaDurationSeconds: mediaDurationSeconds,
39	    );
40	    return result.match((failure) async => left(failure), (dto) async {
41	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
42	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
43	      // own local-persistence step.
44	      try {
45	        await _entriesBox.put(dto.id, dto.toJson());
46	      } catch (error) {
47	        return left(Failure.malformedResponse(message: error.toString()));
48	      }
49	      return right(_toEntry(dto));
50	    });
51	  }
52	
53	  Entry _toEntry(EntryDto dto) => Entry(
54	    id: dto.id,
55	    content: dto.content,
56	    source: dto.source,
57	    chatMessageId: dto.chatMessageId,
58	    occurredAt: dto.occurredAt,
59	    serverRevision: dto.serverRevision,
60	    createdAt: dto.createdAt,
61	    updatedAt: dto.updatedAt,
62	    mediaDurationSeconds: dto.mediaDurationSeconds,
63	  );
64	}
