1	import 'package:fpdart/fpdart.dart';
2	
3	import '../../../../core/failure/failure.dart';
4	import '../../../../core/network/api_client.dart';
5	import '../../domain/entities/entry.dart';
6	import '../models/entry_dto.dart';
7	
8	/// The entries feature's one write call so far (`entries-create`) — posts
9	/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
10	/// pattern.
11	class EntriesRemoteDataSource {
12	  EntriesRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Sends `{content, source}` plus `mediaDurationSeconds` only when
17	  /// non-null (spec-3-2's `source: audio` entries) — this story still
18	  /// never passes `chatMessageId`/`occurredAt` (Boundaries: no `Entry`
19	  /// field beyond the modeled 9; those two are optional in the contract
20	  /// and belong to later stories/epics).
21	  Future<Either<Failure, EntryDto>> create({
22	    required String content,
23	    required EntrySource source,
24	    int? mediaDurationSeconds,
25	  }) async {
26	    final result = await _apiClient.post(
27	      'entries-create',
28	      data: {
29	        'content': content,
30	        'source': source.name,
31	        'mediaDurationSeconds': ?mediaDurationSeconds,
32	      },
33	    );
34	    return result.flatMap((json) {
35	      try {
36	        final data = json['data'] as Map<String, dynamic>;
37	        return right(EntryDto.fromJson(data));
38	      } catch (error) {
39	        // A 200 response that doesn't match the expected shape is a
40	        // client-side parse failure, never a backend-sent code — maps to
41	        // the local-only `malformedResponse` (RNF09: no exception escapes
42	        // unmapped).
43	        return left(Failure.malformedResponse(message: error.toString()));
44	      }
45	    });
46	  }
47	}
