1	import 'package:json_annotation/json_annotation.dart';
2	
3	import '../../domain/entities/entry.dart';
4	
5	part 'entry_dto.g.dart';
6	
7	/// `POST /entries`'s response `data` object (`openapi.yaml:370-456`) —
8	/// decodes exactly the 9 fields [Entry] models (Code Map/Boundaries);
9	/// every other field (`tags`/`piiStatus`/`piiSpans`/`embeddingStatus`) is
10	/// simply ignored by `json_serializable`'s generated `fromJson`, same
11	/// convention `AccountSettingsDto` already uses for the fields it doesn't
12	/// model.
13	///
14	/// [source] serializes/deserializes against [EntrySource]'s own `.name`
15	/// (`json_serializable`'s default enum handling) — the enum's member
16	/// names already match the backend's lowercase `manual`/`audio`/`photo`/
17	/// `chat` strings exactly, so no `@JsonValue` overrides are needed.
18	@JsonSerializable()
19	class EntryDto {
20	  const EntryDto({
21	    required this.id,
22	    required this.content,
23	    required this.source,
24	    required this.chatMessageId,
25	    required this.occurredAt,
26	    required this.serverRevision,
27	    required this.createdAt,
28	    required this.updatedAt,
29	    this.mediaDurationSeconds,
30	  });
31	
32	  final String id;
33	  final String content;
34	  final EntrySource source;
35	  final String? chatMessageId;
36	  final String occurredAt;
37	  final int serverRevision;
38	  final String createdAt;
39	  final String updatedAt;
40	
41	  /// Sent/decoded only when non-null (Code Map) —
42	  /// `@JsonKey(includeIfNull: false)` drops the key from `toJson()`
43	  /// entirely rather than serializing an explicit `null`; a response that
44	  /// omits the key likewise decodes to `null` here, `json_serializable`'s
45	  /// default behavior for a nullable field with no `@JsonKey(required:
46	  /// true)`.
47	  @JsonKey(includeIfNull: false)
48	  final int? mediaDurationSeconds;
49	
50	  factory EntryDto.fromJson(Map<String, dynamic> json) =>
51	      _$EntryDtoFromJson(json);
52	
53	  /// Also the exact shape written to the `entries` Hive box (Design
54	  /// Notes: "raw `Map<String, dynamic>` via `EntryDto.toJson()`").
55	  Map<String, dynamic> toJson() => _$EntryDtoToJson(this);
56	}
