9	/// The `entries` Hive box's name — the first `hive_ce` box in the app
10	/// (Code Map). A raw `Box<Map>`, not a generated `HiveObject`/
11	/// `TypeAdapter` (Design Notes: avoids adapter codegen for a box nothing
12	/// reads yet).
13	const entriesBoxName = 'entries';
14	
15	/// Registers the `entries` feature into the project's single `get_it`
16	/// instance (`sl`) — mirrors `features/account/account_injection.dart`'s
17	/// pattern. Called from `setupCoreDependencies()` right after
18	/// `Hive.initFlutter()` (Code Map), which must already have run by the
19	/// time this opens its box.
20	Future<void> registerEntriesFeature() async {
21	  final entriesBox = await Hive.openBox<Map>(entriesBoxName);
22	  sl.registerSingleton<Box<Map>>(entriesBox);
23	
24	  sl.registerLazySingleton<EntriesRemoteDataSource>(
25	    () => EntriesRemoteDataSource(sl<ApiClient>()),
26	  );
27	
28	  sl.registerLazySingleton<EntriesRepository>(
29	    () => EntriesRepositoryImpl(
30	      remoteDataSource: sl<EntriesRemoteDataSource>(),
31	      entriesBox: sl<Box<Map>>(),
32	    ),
33	  );
34	}
