3	/// AD-12 — generic fetch-lifecycle state for screens with exactly one data
4	/// source and one fetch (`idle` / `loading` / `data` / `error`).
5	///
6	/// Used only where that shape fits (e.g. a single `GET` on screen entry).
7	/// RF02's capture pipeline, RF04's chat stream and RF07's composite
8	/// auth × sync × data state each define their own sealed state class instead
9	/// — never forced into this one (AD-12).
10	sealed class Resource<T> {
11	  const Resource();
12	}
13	
14	final class ResourceIdle<T> extends Resource<T> {
15	  const ResourceIdle();
16	}
17	
18	final class ResourceLoading<T> extends Resource<T> {
19	  const ResourceLoading();
20	}
21	
22	final class ResourceData<T> extends Resource<T> {
23	  const ResourceData(this.data);
24	
25	  final T data;
26	}
27	
28	final class ResourceError<T> extends Resource<T> {
29	  const ResourceError(this.failure);
30	
31	  final Failure failure;
32	}
