1	import 'dart:async';
2	import 'dart:io';
3	
4	import 'package:flutter/material.dart';
5	import 'package:flutter/semantics.dart';
6	import 'package:flutter/services.dart';
7	import 'package:flutter_bloc/flutter_bloc.dart';
8	
9	import '../../../../core/design_tokens.dart';
10	import '../../../../core/widgets/app_button.dart';
11	import '../cubit/audio_entry_cubit.dart';
12	import '../cubit/photo_entry_cubit.dart';
13	import '../cubit/text_entry_cubit.dart';
14	
15	/// Drops focus *before* popping the sheet's route, for every dismissal
16	/// path this widget triggers programmatically ("x", Salvar success) —
17	/// root cause of the keyboard staying open over the Home screen after
18	/// close (physical-device bug report): the previous fix only unfocused
19	/// *after* `showModalBottomSheet`'s own `Future` resolved
20	/// (`InsertionModal.show`), i.e. after `Navigator.pop()` had already
21	/// started tearing the sheet's `TextField` down — on a physical iOS
22	/// device that race loses often enough for the native keyboard's "hide"
23	/// message to never reach the platform side, even though the
24	/// `FocusNode`/`TextInputConnection` state Flutter itself tracks (and
25	/// what `tester.testTextInput.isVisible` reads in a widget test) still
26	/// looks correctly unfocused, which is why unit tests alone passed
27	/// without the bug actually being fixed. Unfocusing first, while the
28	/// field is still fully mounted and focused, gives the hide message a
29	/// clean runway before the pop/teardown begins.
30	void _unfocusAndPop(BuildContext context) {
31	  FocusManager.instance.primaryFocus?.unfocus();
32	  Navigator.of(context).pop();
33	}
34	
35	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
36	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Texto,
37	/// Áudio and Foto are all functional as of spec-3-3 (Boundaries).
38	class InsertionModal extends StatelessWidget {
39	  const InsertionModal({
40	    required this.cubit,
41	    required this.audioCubit,
42	    required this.photoCubit,
43	    super.key,
44	  });
45	
46	  final TextEntryCubit cubit;
47	  final AudioEntryCubit audioCubit;
48	  final PhotoEntryCubit photoCubit;
49	
50	  /// Presents the modal exactly as the Boundaries dictate:
51	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
52	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
53	  /// this widget's own `Container`, not Material's `elevation` double —
54	  /// same convention `ConfirmationDialog`'s card already uses), and a
55	  /// `durationSheetUp` entrance that collapses to zero under Reduce
56	  /// Motion (`MediaQuery.disableAnimations`).
57	  ///
58	  /// [cubit]/[audioCubit]/[photoCubit] are all fresh, `get_it`-factory-
59	  /// scoped instances — one trio per "+" tap (Boundaries: "Modal open
60	  /// resets") — closed here once the sheet is gone, regardless of how it
61	  /// closed (Salvar success, "x", swipe-down, or barrier dismiss) — the
62	  /// caller never has to remember to do this itself.
63	  static Future<void> show(
64	    BuildContext context, {
65	    required TextEntryCubit cubit,
66	    required AudioEntryCubit audioCubit,
67	    required PhotoEntryCubit photoCubit,
68	  }) async {
69	    final reduceMotion = MediaQuery.of(context).disableAnimations;
70	    final controller =
71	        BottomSheet.createAnimationController(Navigator.of(context))
72	          ..duration = reduceMotion
73	              ? Duration.zero
74	              : DesignTokens.durationSheetUp
75	          // Boundaries only names the entrance, but Reduce Motion should
76	          // collapse the exit the same way — otherwise dismissing the
77	          // sheet would still animate for anyone who asked for no motion.
78	          ..reverseDuration = reduceMotion ? Duration.zero : null;
79	    try {
80	      await showModalBottomSheet<void>(
81	        context: context,
82	        isScrollControlled: true,
83	        // Without this, the sheet's max-height constraint is the full
84	        // screen height including the status bar — with `isScrollControlled`
85	        // letting it grow to content height, a tall keyboard + content
86	        // combination pushed it up under the status bar/notch.
87	        useSafeArea: true,
88	        barrierColor: DesignTokens.colorScrimHeavy,
89	        backgroundColor: Colors.transparent,
90	        elevation: 0,
91	        transitionAnimationController: controller,
92	        builder: (_) => InsertionModal(
93	          cubit: cubit,
94	          audioCubit: audioCubit,
95	          photoCubit: photoCubit,
96	        ),
97	      );
98	      // Every dismissal path (Salvar success, "x", swipe-down, barrier tap)
99	      // routes back through this single `await`. Salvar/"x" already
100	      // unfocus *before* popping (`_unfocusAndPop`); swipe-down and
101	      // barrier-tap pop directly inside `showModalBottomSheet`'s own
102	      // drag/tap handling (`BottomSheet`'s `onClosing`), with no hook
103	      // this widget can run *before* that pop. By the time this `await`
104	      // resolves for either of those two paths, the sheet's `TextField`
105	      // may already be mid-teardown — root cause of the bug report this
106	      // fixes: on a physical iOS device, `FocusNode.unfocus()` alone
107	      // only reliably hides the keyboard if the field's
108	      // `TextInputConnection` is still intact at the moment it's called;
109	      // past that point it can lose the race and leave the native
110	      // keyboard on screen (reproduced only on hardware — the
111	      // `TestWidgetsFlutterBinding` used under `flutter test` has no
112	      // such race, which is why the previous attempt at this same fix
113	      // passed its unit tests without the bug actually being fixed).
114	      // `SystemChannels.textInput`'s own `TextInput.hide` call sidesteps
115	      // that race entirely — it tells the platform embedder to hide the
116	      // on-screen keyboard directly, independent of whether a Dart-side
117	      // `TextInputConnection` is still attached.
118	      FocusManager.instance.primaryFocus?.unfocus();
119	      await SystemChannels.textInput.invokeMethod<void>('TextInput.hide');
120	    } finally {
121	      // `showModalBottomSheet`'s own Future completes as soon as the
122	      // route is popped — *before* the exit (`reverse()`) animation the
123	      // framework drives on this same controller actually finishes.
124	      // Disposing immediately would cancel that animation's ticker
125	      // mid-flight, permanently freezing the sheet on screen (its
126	      // `AnimatedBuilder` keeps rendering the controller's last value,
127	      // and the route itself never reaches `AnimationStatus.dismissed`
128	      // to be removed from the `Overlay`). Documented behavior
129	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
130	      // caller is responsible for disposing it when the controller is
131	      // no longer needed") — waiting for `dismissed` first is that
132	      // "no longer needed" point.
133	      if (!controller.isDismissed) {
134	        final animationDone = Completer<void>();
135	        void onStatusChange(AnimationStatus status) {
136	          if (status == AnimationStatus.dismissed) {
137	            animationDone.complete();
138	          }
139	        }
140	
141	        controller.addStatusListener(onStatusChange);
142	        await animationDone.future;
143	        controller.removeStatusListener(onStatusChange);
144	      }
145	      controller.dispose();
146	      // Review finding: each of the three cubits' cancel+close pair is
147	      // isolated in its own try/finally — without this, an exception
148	      // from an earlier step (e.g. `audioCubit.cancel()`) would skip
149	      // every later cleanup step entirely, leaking whichever cubit never
150	      // got to run its own `cancel()`/`close()`.
151	      try {
152	        await cubit.close();
153	      } finally {
154	        try {
155	          // Review finding: dismissing the whole modal while recording/
156	          // processing (the "x" button, swipe-down, or barrier tap — as
157	          // opposed to switching to another tab, which already went
158	          // through this same `cancel()`) never stopped the native
159	          // recording session; `close()` alone only cancels the
160	          // elapsed-seconds timer, not the recorder itself.
161	          // `discardPreserved: true` — unlike a tab switch, there's no
162	          // "switch back later" to preserve a transcribed/failed
163	          // recording for, so its temp file must be cleaned up here too
164	          // (Review finding) rather than leaking on disk forever once
165	          // `close()` below makes the cubit unreachable.
166	          await audioCubit.cancel(discardPreserved: true);
167	        } finally {
168	          try {
169	            await audioCubit.close();
170	          } finally {
171	            try {
172	              // Review finding: every `image_picker` pick writes a real
173	              // OS temp file — the comment this replaced incorrectly
174	              // claimed Foto "never creates a temp file of its own".
175	              // Same `discardPreserved: true` rationale as Áudio's own
176	              // call above: there's no "switch back later" once the
177	              // whole modal is closing, so a preserved
178	              // `PhotoRecognized`/`PhotoError`'s picked file must be
179	              // cleaned up here too rather than leaking on disk forever.
180	              await photoCubit.cancel(discardPreserved: true);
181	            } finally {
182	              await photoCubit.close();
183	            }
184	          }
185	        }
186	      }
187	    }
188	  }
189	
190	  @override
191	  Widget build(BuildContext context) {
192	    return MultiBlocProvider(
193	      providers: [
194	        BlocProvider.value(value: cubit),
195	        BlocProvider.value(value: audioCubit),
196	        BlocProvider.value(value: photoCubit),
197	      ],
198	      child: const _InsertionModalBody(),
199	    );
200	  }
201	}
202	
203	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
204	/// given emission is a genuine transition worth announcing — e.g.
205	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
206	/// repeatedly and must never re-announce "Gravando áudio" every second.
207	enum _AudioAnnounceKind {
208	  idle,
209	  recording,
210	  processing,
211	  transcribed,
212	  saving,
213	  saved,
214	  error,
215	}
216	
217	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) =>
218	    switch (state) {
219	      AudioIdle() => _AudioAnnounceKind.idle,
220	      AudioRecording() => _AudioAnnounceKind.recording,
221	      AudioProcessing() => _AudioAnnounceKind.processing,
222	      AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
223	      AudioTranscribed() => _AudioAnnounceKind.transcribed,
224	      AudioSaved() => _AudioAnnounceKind.saved,
225	      AudioError() => _AudioAnnounceKind.error,
226	    };
227	
228	/// Same "only announce a genuine transition" role as [_AudioAnnounceKind],
229	/// for `PhotoEntryCubit`.
230	enum _PhotoAnnounceKind { idle, processing, recognized, saving, saved, error }
231	
232	_PhotoAnnounceKind _photoAnnounceKindOf(PhotoCaptureState state) =>
233	    switch (state) {
234	      PhotoIdle() => _PhotoAnnounceKind.idle,
235	      PhotoProcessing() => _PhotoAnnounceKind.processing,
236	      PhotoRecognized(saving: true) => _PhotoAnnounceKind.saving,
237	      PhotoRecognized() => _PhotoAnnounceKind.recognized,
238	      PhotoSaved() => _PhotoAnnounceKind.saved,
239	      PhotoError() => _PhotoAnnounceKind.error,
240	    };
241	
242	class _InsertionModalBody extends StatefulWidget {
243	  const _InsertionModalBody();
244	
245	  @override
246	  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
247	}
248	
249	class _InsertionModalBodyState extends State<_InsertionModalBody> {
250	  final _textController = TextEditingController();
251	
252	  /// The Áudio tab's own text field controller — lifted up here rather
253	  /// than owned by `_AudioTab` itself so it survives `_AudioTab` being
254	  /// rebuilt on every `AudioCaptureState` change without losing cursor
255	  /// position/focus, same rationale as [_textController] living here
256	  /// instead of inside `_TextoTab`.
257	  final _audioTextController = TextEditingController();
258	
259	  /// The Foto tab's own text field controller — same "lifted up" rationale
260	  /// as [_audioTextController].
261	  final _photoTextController = TextEditingController();
262	
263	  /// The last `AudioTranscribed.path` this controller's text was synced
264	  /// from — only a *new* transcription (a different/first path) resets
265	  /// the controller's text; the user's own edits via `onChanged` never
266	  /// get clobbered by an unrelated rebuild.
267	  String? _lastSyncedAudioPath;
268	
269	  /// Same role as [_lastSyncedAudioPath], for `PhotoRecognized.path` — a
270	  /// *new* `PhotoRecognized` for a path not yet synced (the initial OCR
271	  /// success, or a retried OCR landing after an error that never
272	  /// synced) overwrites the controller; the user's own edits (which
273	  /// re-emit the same path) never do.
274	  String? _lastSyncedPhotoPath;
275	
276	  /// Tracks the previously-seen `activeTab` so the listener can tell a
277	  /// genuine tab switch apart from the many other `TextEntryIdle`
278	  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
279	  /// initialized from the cubit's own current state so the very first
280	  /// comparison (before any emission the listener sees) is still correct.
281	  late CaptureTab _lastAnnouncedTab;
282	
283	  /// Same "only announce a genuine transition" guard as [_lastAnnouncedTab],
284	  /// for `AudioEntryCubit` (see [_audioAnnounceKindOf]).
285	  late _AudioAnnounceKind _lastAudioAnnouncedKind;
286	
287	  /// Same role as [_lastAudioAnnouncedKind], for `PhotoEntryCubit` (see
288	  /// [_photoAnnounceKindOf]).
289	  late _PhotoAnnounceKind _lastPhotoAnnouncedKind;
290	
291	  @override
292	  void initState() {
293	    super.initState();
294	    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
295	    _lastAudioAnnouncedKind = _audioAnnounceKindOf(
296	      context.read<AudioEntryCubit>().state,
297	    );
298	    _lastPhotoAnnouncedKind = _photoAnnounceKindOf(
299	      context.read<PhotoEntryCubit>().state,
300	    );
301	  }
302	
303	  @override
304	  void dispose() {
305	    _textController.dispose();
306	    _audioTextController.dispose();
307	    _photoTextController.dispose();
308	    super.dispose();
309	  }
310	
311	  // Labels for the 3 tabs, shared between the announcement below and
312	  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
313	  // `selectTab`'s announcement needs the label for whichever tab the
314	  // user just switched *to*, not the cubit's own (enum-only) state.
315	  static const _tabLabels = {
316	    CaptureTab.texto: 'Texto',
317	    CaptureTab.audio: 'Áudio',
318	    CaptureTab.foto: 'Foto',
319	  };
320	
321	  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
322	  // (this app is iOS-only) doesn't reliably treat a live-region subtree
323	  // update as an announcement on its own, so every state change this
324	  // story introduces — saving, success, failure, and a tab switch — is
325	  // spoken explicitly here instead (Acceptance Criteria: "no
326	  // color/animation alone").
327	  Future<void> _announce(String message) async {
328	    if (!mounted) {
329	      return;
330	    }
331	    await SemanticsService.sendAnnouncement(
332	      View.of(context),
333	      message,
334	      TextDirection.ltr,
335	    );
336	  }
