388	  void _onAudioStateChange(BuildContext context, AudioCaptureState state) {
389	    if (state is AudioTranscribed && state.path != _lastSyncedAudioPath) {
390	      _lastSyncedAudioPath = state.path;
391	      _audioTextController.text = state.text;
392	    }
393	    final kind = _audioAnnounceKindOf(state);
394	    if (kind == _lastAudioAnnouncedKind) {
395	      return;
396	    }
397	    _lastAudioAnnouncedKind = kind;
398	    switch (state) {
399	      case AudioRecording():
400	        _announce('Gravando áudio');
401	      case AudioProcessing():
402	        _announce('Transcrevendo áudio');
403	      case AudioTranscribed(saving: true):
404	        _announce('Salvando registro');
405	      case AudioTranscribed():
406	        _announce('Transcrição concluída. Revise o texto antes de salvar.');
407	      case AudioError(message: final message):
408	        _announce(message);
409	      case AudioSaved():
410	        // Same "wait for the announcement" rationale as
411	        // `TextEntrySaved` above.
412	        unawaited(
413	          _announce('Registro salvo').then((_) {
414	            if (context.mounted) {
415	              _unfocusAndPop(context);
416	            }
417	          }),
418	        );
419	      case AudioIdle():
420	        // Review finding: the one `AudioCaptureState` transition
421	        // previously never announced — reachable today only via
422	        // `cancel()` resetting from `AudioRecording` (a tab switch away
423	        // mid-recording), which happened to already be covered by the
424	        // separate tab-switch announcement above, masking the gap.
425	        _announce('Gravação cancelada');
426	    }
427	  }
